ng, and what it buys.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Funding ask.]"}]}]}'::jsonb,
  metadata = '{"document_type":"business_plan","category":"professional","use_cases":["Startup planning","Fundraising","Strategic planning"],"supported_views":["wiki","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"stage","field_label":"Stage","field_type":"select","options":["idea","pre_seed","seed","series_a","growth"],"ai_fill_enabled":true},{"field_key":"industry","field_label":"Industry","field_type":"text","ai_fill_enabled":true},{"field_key":"funding_target","field_label":"Funding target","field_type":"number","options":{"unit":"currency"},"ai_fill_enabled":false},{"field_key":"arr_target","field_label":"ARR target","field_type":"number","options":{"unit":"currency"},"ai_fill_enabled":false},{"field_key":"client","field_label":"Client","field_type":"relation","ai_fill_enabled":false}],"default_properties":{"status":"draft","stage":"idea"}}'::jsonb
where slug = 'business-plan'
  and coalesce(is_system, false) = true
  and workspace_id is null;

-- Promote client to relation where it already exists as text.
update metadata_schemas
set field_type = 'relation', ai_fill_enabled = false
where field_key = 'client'
  and field_type = 'text';

insert into metadata_schemas (workspace_id, field_key, field_label, field_type, options, ai_fill_enabled)
select ms.workspace_id, v.field_key, v.field_label, v.field_type, v.options, v.ai_fill_enabled
from (
  select distinct workspace_id from metadata_schemas
  where field_key in ('content_status', 'seo_status', 'batch_status', 'audit_status', 'stage', 'campaign')
) ms
cross join (
  values
    ('funnel_stage', 'Funnel stage (AARRR)', 'select', '["acquisition","activation","retention","referral","revenue"]'::jsonb, true),
    ('search_volume', 'Search volume', 'number', null::jsonb, false),
    ('keyword_difficulty', 'Keyword difficulty', 'number', null::jsonb, false),
    ('maturity_domain', 'Audit domain', 'select', '["ux","tech_stack","data_privacy","growth_ops","holistic"]'::jsonb, true),
    ('funding_target', 'Funding target', 'number', '{"unit":"currency"}'::jsonb, false),
    ('arr_target', 'ARR target', 'number', '{"unit":"currency"}'::jsonb, false)
) as v(field_key, field_label, field_type, options, ai_fill_enabled)
where not exists (
  select 1 from metadata_schemas e
  where e.workspace_id = ms.workspace_id and e.field_key = v.field_key
);
